struct rule {
    int accept;               /* 1 = accept, 0 = drop */
    int proto;                /* 0 = any, 6 = TCP, 17 = UDP */
    unsigned src_net, src_mask;
    int dport_lo, dport_hi;
};

struct pkt {
    int proto;
    unsigned src;
    int dport;
};

int filter_packet(const struct rule *r, int n, const struct pkt *p, int policy) { (void)r; (void)n; (void)p; return policy; }
